CREATE OR REPLACE FUNCTION public.audit_admin_write()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare row_data jsonb; target text; ctx public.impersonation_sessions%rowtype;
begin
  if (select auth.uid()) is null then return coalesce(new, old); end if;
  row_data := case when tg_op = 'DELETE' then to_jsonb(old) else to_jsonb(new) end;
  target := coalesce(row_data->>'id', row_data->>'company_id', row_data->>'asset_id', row_data->>'asset_key');
  select * into ctx from public.impersonation_sessions where actor_real_auth_user_id=(select auth.uid()) and ended_at is null and expires_at>now() limit 1;
  insert into public.admin_audit_log(actor_auth_user_id,resource,action,target_id,result,usuario_contexto_affiliate_id,impersonation_session_id,reason)
  values ((select auth.uid()),tg_table_name,tg_op,target,'SUCCESS',ctx.usuario_contexto_affiliate_id,ctx.id,ctx.reason);
  return coalesce(new, old);
end;
$function$

CREATE OR REPLACE FUNCTION public.capture_document_requirements_snapshot()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare v_type text;v_key text;
begin
  if new.document_requirements_snapshot is not null then raise exception 'DOCUMENT_REQUIREMENTS_SNAPSHOT_SERVER_ONLY' using errcode='42501'; end if;
  if new.membership_offering_id is not null then v_type:='MEMBERSHIP';v_key:=new.membership_offering_id::text;
  elsif new.program_id='prestamo' then v_type:='PROGRAM';v_key:='prestamo';
  elsif new.financial_submission_snapshot->>'contract_version'='PROGRAM_PRODUCT_PAYMENT_V1' then v_type:='PROGRAM';v_key:='prestamo';
  elsif new.product_id is not null then v_type:='PRODUCT';v_key:=new.product_id::text;
  elsif new.program_item_id is not null then v_type:='PROGRAM';v_key:=new.program_item_id::text;
  else raise exception 'DOCUMENT_SCOPE_NOT_AVAILABLE' using errcode='22023'; end if;
  select coalesce(jsonb_agg(jsonb_build_object(
    'requirement_id',r.requirement_id,'document_type_id',r.document_type_id,'code',r.document_type_code,'label',r.document_type_label,
    'required',r.required,'allow_verified_reuse',r.allow_verified_reuse,'sort_order',r.sort_order,'inherited',r.inherited,
    'source_scope_type',r.source_scope_type,'source_scope_key',r.source_scope_key,'scope_type',v_type,'scope_key',v_key
  ) order by r.sort_order,r.document_type_label),'[]'::jsonb) into new.document_requirements_snapshot
  from public.resolve_effective_document_requirements(v_type,v_key) r;
  return new;
end $function$

CREATE OR REPLACE FUNCTION public.capture_program_request_impersonation()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$ declare ctx public.impersonation_sessions%rowtype;
begin
  select * into ctx from public.impersonation_sessions
   where actor_real_auth_user_id=(select auth.uid()) and ended_at is null and expires_at>now() limit 1;
  if ctx.id is not null then
    if not public.is_active_admin() or new.affiliate_id is distinct from ctx.usuario_contexto_affiliate_id then
      raise exception 'IMPERSONATION_CONTEXT_INVALID' using errcode='42501';
    end if;
    new.usuario_contexto_affiliate_id:=ctx.usuario_contexto_affiliate_id;
    new.impersonation_session_id:=ctx.id;
    new.impersonation_reason:=ctx.reason;
    new.source_context:=coalesce(new.source_context,'{}'::jsonb)||jsonb_build_object(
      'assisted',true,'actor_real_auth_user_id',auth.uid(),'usuario_contexto_affiliate_id',ctx.usuario_contexto_affiliate_id,
      'impersonation_session_id',ctx.id,'impersonation_reason',ctx.reason
    );
  end if;
  return new;
end $function$

CREATE OR REPLACE FUNCTION public.capture_program_request_workflow_snapshot()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$ declare v_snapshot jsonb;
begin
  v_snapshot:=public.build_program_request_workflow_snapshot(new);
  new.workflow_id:=(v_snapshot->>'workflow_id')::uuid;
  new.workflow_version:=(v_snapshot->>'workflow_version')::integer;
  new.workflow_snapshot:=v_snapshot;
  return new;
end $function$

CREATE OR REPLACE FUNCTION public.create_program_request(p_program_item_id uuid, p_product_id uuid, p_quantity integer, p_notes text, p_signature_data text, p_terms_accepted boolean, p_idempotency_key uuid)
 RETURNS program_requests
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare
  v_affiliate public.affiliates%rowtype;
  v_item public.program_catalog_items%rowtype;
  v_product public.marketplace_products%rowtype;
  v_row public.program_requests%rowtype;
  v_request_type text;
  v_status text;
  v_financial_status text;
begin
  if (p_program_item_id is null) = (p_product_id is null) then
    raise exception 'REQUEST_TARGET_REQUIRED' using errcode='22023';
  end if;
  if p_idempotency_key is null then raise exception 'IDEMPOTENCY_KEY_REQUIRED' using errcode='22023'; end if;
  if not coalesce(p_terms_accepted,false) or nullif(btrim(coalesce(p_signature_data,'')),'') is null then
    raise exception 'SIGNATURE_AND_TERMS_REQUIRED' using errcode='22023';
  end if;

  select a.* into v_affiliate from public.affiliates a where a.id=public.get_effective_affiliate_id();
  if v_affiliate.id is null then raise exception 'AFFILIATE_REQUIRED' using errcode='P0001'; end if;
  if nullif(btrim(coalesce(v_affiliate.numero_control,'')),'') is null then raise exception 'AFFILIATE_CONTROL_REQUIRED' using errcode='P0001'; end if;

  select * into v_row from public.program_requests
  where affiliate_id=v_affiliate.id and idempotency_key=p_idempotency_key;
  if v_row.id is not null then return v_row; end if;

  if p_program_item_id is not null then
    select * into v_item from public.program_catalog_items where id=p_program_item_id and enabled and request_mode='supabase';
    if v_item.id is null then raise exception 'PROGRAM_NOT_REQUESTABLE' using errcode='P0001'; end if;
    v_request_type:=case when v_item.requires_quote then 'quote' else 'benefit' end;
    v_status:=case when v_item.legacy_boundary then 'requires_financial_processing' else 'submitted' end;
    v_financial_status:=case when v_item.legacy_boundary then 'pending' else null end;
    insert into public.program_requests(
      actor_real_auth_user_id,affiliate_id,numero_control,program_id,program_item_id,request_type,status,
      quantity,notes,signature_data,terms_accepted,source_context,financial_processing_status,idempotency_key
    ) values (
      (select auth.uid()),v_affiliate.id,v_affiliate.numero_control,v_item.program_key,v_item.id,v_request_type,v_status,
      greatest(1,least(coalesce(p_quantity,1),999)),left(nullif(btrim(coalesce(p_notes,'')),''),2000),p_signature_data,true,
      jsonb_build_object('source','sutiapp','catalog','program_catalog_items','requires_quote',v_item.requires_quote),v_financial_status,p_idempotency_key
    ) returning * into v_row;
  else
    select p.* into v_product from public.marketplace_products p
    where p.id=p_product_id and p.enabled and exists(select 1 from public.companies c where c.id=p.company_id and c.enabled);
    if v_product.id is null then raise exception 'PRODUCT_NOT_REQUESTABLE' using errcode='P0001'; end if;
    v_request_type:=case when v_product.requires_quote then 'quote' else 'benefit' end;
    insert into public.program_requests(
      actor_real_auth_user_id,affiliate_id,numero_control,program_id,product_id,company_id,request_type,status,
      quantity,notes,signature_data,terms_accepted,source_context,idempotency_key
    ) values (
      (select auth.uid()),v_affiliate.id,v_affiliate.numero_control,'marketplace',v_product.id,v_product.company_id,v_request_type,'submitted',
      greatest(1,least(coalesce(p_quantity,1),999)),left(nullif(btrim(coalesce(p_notes,'')),''),2000),p_signature_data,true,
      jsonb_build_object('source','sutiapp','catalog','marketplace_products','requires_quote',v_product.requires_quote),p_idempotency_key
    ) returning * into v_row;
  end if;
  return v_row;
exception when unique_violation then
  select * into v_row from public.program_requests where affiliate_id=v_affiliate.id and idempotency_key=p_idempotency_key;
  if v_row.id is not null then return v_row; end if;
  raise;
end $function$

CREATE OR REPLACE FUNCTION public.enforce_personalized_financial_submission()
 RETURNS trigger
 LANGUAGE plpgsql
 SET search_path TO ''
AS $function$ begin
  if tg_op='INSERT' and new.program_id='prestamo' then
    if coalesce(auth.role(),'')<>'service_role' then
      raise exception 'FINANCIAL_CONFIRMATION_REQUIRED' using errcode='42501';
    end if;
    if new.financial_submission_snapshot is null
       or not(new.financial_submission_snapshot?'financialResult')
       or not(new.financial_submission_snapshot?'criteria_source_fingerprint')
       or not(new.financial_submission_snapshot?'profile_fingerprint')
       or not(new.financial_submission_snapshot?'confirmed_at') then
      raise exception 'FINANCIAL_SUBMISSION_SNAPSHOT_REQUIRED' using errcode='22023';
    end if;
  elsif tg_op='UPDATE' and new.financial_submission_snapshot is distinct from old.financial_submission_snapshot then
    raise exception 'FINANCIAL_SUBMISSION_SNAPSHOT_IMMUTABLE' using errcode='P0001';
  end if;
  return new;
end $function$

CREATE OR REPLACE FUNCTION public.enforce_program_catalog_requestability()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare v_item public.program_catalog_items%rowtype;
begin
  if new.program_item_id is null then return new; end if;
  select * into v_item from public.program_catalog_items where id=new.program_item_id;
  if v_item.id is null then raise exception 'PROGRAM_PRODUCT_NOT_FOUND' using errcode='P0001'; end if;
  if v_item.sold then raise exception 'PROGRAM_PRODUCT_SOLD' using errcode='P0001'; end if;
  if v_item.commercial_mode='DIRECT_CONTACT' then
    raise exception 'PROGRAM_PRODUCT_DIRECT_CONTACT_ONLY' using errcode='P0001';
  end if;
  if v_item.program_key='prestamo' then return new; end if;
  if v_item.commercial_mode='PAYROLL_QUOTE' and new.request_type='quote'
     and new.financial_submission_snapshot is null then return new; end if;
  if new.request_type='benefit'
     and new.financial_submission_snapshot->>'contract_version'='PROGRAM_PRODUCT_PAYMENT_V1' then return new; end if;
  raise exception 'PROGRAM_PRODUCT_PAYMENT_FLOW_REQUIRED' using errcode='P0001';
end $function$

CREATE OR REPLACE FUNCTION public.protect_approved_financial_request_state()
 RETURNS trigger
 LANGUAGE plpgsql
 SET search_path TO ''
AS $function$ begin
  if old.financial_approval_snapshot is not null and new.status is distinct from old.status then
    raise exception 'APPROVED_FINANCIAL_REQUEST_STATUS_IMMUTABLE' using errcode='P0001';
  end if;
  return new;
end $function$

CREATE OR REPLACE FUNCTION public.protect_financial_request_snapshots()
 RETURNS trigger
 LANGUAGE plpgsql
 SET search_path TO ''
AS $function$ begin
  if tg_op='INSERT' and new.financial_processing_status is not null then
    select jsonb_build_object('affiliate_id',a.id,'numero_control',a.numero_control,'financial_union_code',a.financial_union_code,
      'financial_union',u.label,'financial_employee_category_code',a.financial_employee_category_code,
      'financial_employee_category',c.label,'financial_employee_type',a.financial_employee_type,
      'financial_affiliation_status',a.financial_affiliation_status,'financial_employment_status',a.financial_employment_status,
      'profile_version',a.financial_profile_version,'captured_at',now()) into new.financial_profile_snapshot
    from public.affiliates a
    left join public.segmentation_catalog_entries u on u.catalog_type='union' and u.code=a.financial_union_code and u.enabled
    left join public.segmentation_catalog_entries c on c.catalog_type='employment_category' and c.code=a.financial_employee_category_code and c.enabled
    where a.id=new.affiliate_id;
  elsif tg_op='UPDATE' then
    if new.financial_profile_snapshot is distinct from old.financial_profile_snapshot or old.financial_approval_snapshot is not null and new.financial_approval_snapshot is distinct from old.financial_approval_snapshot then
      raise exception 'FINANCIAL_SNAPSHOT_IMMUTABLE' using errcode='P0001';
    end if;
    if new.financial_processing_status is not null and new.status='approved' and old.status is distinct from 'approved' and new.financial_approval_snapshot is null then
      raise exception 'FINANCIAL_APPROVAL_SNAPSHOT_REQUIRED' using errcode='P0001';
    end if;
    if old.requested_amount is not null and (new.requested_amount is distinct from old.requested_amount or new.requested_term is distinct from old.requested_term or new.requested_term_semantics is distinct from old.requested_term_semantics) then
      raise exception 'FINANCIAL_REQUEST_TERMS_IMMUTABLE' using errcode='P0001';
    end if;
  end if;
  return new;
end $function$

CREATE OR REPLACE FUNCTION public.respond_program_request_quote(p_request_id uuid, p_amount numeric, p_note text, p_valid_until date)
 RETURNS program_requests
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare v_row public.program_requests%rowtype;
begin
  select * into v_row from public.program_requests where id=p_request_id;
  if v_row.id is null or v_row.request_type<>'quote' then raise exception 'QUOTE_NOT_FOUND' using errcode='P0001'; end if;
  if not (public.has_admin_permission('program_requests.write') or (v_row.company_id is not null and public.is_marketplace_company_member(v_row.company_id,'quotes'))) then
    raise exception 'QUOTE_DENIED' using errcode='42501';
  end if;
  if p_amount is null or p_amount<=0 then raise exception 'QUOTE_AMOUNT_INVALID' using errcode='22023'; end if;
  update public.program_requests set status='approved',quoted_amount=p_amount,quote_note=left(nullif(btrim(coalesce(p_note,'')),''),2000),
    valid_until=p_valid_until,responded_by_auth_user_id=(select auth.uid()),responded_at=now(),seen_at=null,updated_at=now()
  where id=p_request_id returning * into v_row;
  return v_row;
end $function$

CREATE OR REPLACE FUNCTION public.set_h0072_updated_at()
 RETURNS trigger
 LANGUAGE plpgsql
 SET search_path TO ''
AS $function$
begin
  new.updated_at = now();
  return new;
end;
$function$

CREATE OR REPLACE FUNCTION public.sync_program_request_tracking_from_status()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare v_stage jsonb;v_first jsonb;v_dates jsonb;v_at timestamptz;
begin
  select s into v_stage from jsonb_array_elements(new.workflow_snapshot->'stages') s
  where s->'status_references'?new.status
    and (case when new.status in('rejected','cancelled') then s->>'outcome'<>'success' else s->>'outcome'<>'failure' end)
  order by (s->>'sort_order')::integer,s->>'id' limit 1;
  if v_stage is null then raise exception 'REQUEST_WORKFLOW_STATUS_UNMAPPED' using errcode='22023'; end if;
  select s into v_first from jsonb_array_elements(new.workflow_snapshot->'stages') s
    order by (s->>'sort_order')::integer,s->>'id' limit 1;
  select coalesce(stage_dates,'{}'::jsonb) into v_dates from public.operational_request_tracking where request_id=new.id;
  v_dates:=coalesce(v_dates,'{}'::jsonb);
  if coalesce((v_first->>'captures_date')::boolean,false) and not(v_dates?(v_first->>'id')) then
    v_dates:=v_dates||jsonb_build_object(v_first->>'id',new.created_at);
  end if;
  v_at:=case when tg_op='INSERT' then new.created_at else now() end;
  if coalesce((v_stage->>'captures_date')::boolean,false) and not(v_dates?(v_stage->>'id')) then
    v_dates:=v_dates||jsonb_build_object(v_stage->>'id',v_at);
  end if;
  perform set_config('app.workflow_change_reason',case when tg_op='INSERT' then 'Alta de solicitud' else 'Estado de solicitud: '||old.status||' -> '||new.status end,true);
  insert into public.operational_request_tracking(request_id,workflow_id,current_stage_id,stage_dates)
  values(new.id,new.workflow_id,(v_stage->>'id')::uuid,v_dates)
  on conflict(request_id) do update set workflow_id=excluded.workflow_id,current_stage_id=excluded.current_stage_id,stage_dates=excluded.stage_dates;
  return new;
end $function$
